/* ---------- flexible vertical rhythm ---------- */
/* Spacers grow in proportion to their master values, so the master's
   vertical rhythm is preserved on every canvas. They stop at --gmax x
   their base size; any surplus beyond that is taken by the photo band
   (which simply crops taller) instead of pulling the sections apart. */
--gmax:3.2;
.sp{
  flex:1 1 auto;
  flex-grow:var(--g);
  min-height:calc(var(--g) * 1px * var(--s));
  max-height:calc(var(--g) * var(--gmax) * 1px * var(--s));
}
.sp.top   {--g:40;}
.sp.hero  {--g:30;}
.sp.cands {--g:32;}
.sp.cta   {--g:30;}
.sp.steps {--g:28;}
.sp.foot  {--g:26;}
.sp.bottom{--g:34;}

